import * as React from "react"

import { layerProps, type LayerProps } from "@/components/standard/layer"

const maskKinds = ["fade", "edges", "vignette", "spotlight"] as const

type MaskKind = (typeof maskKinds)[number]

type MaskDirection = "top" | "right" | "bottom" | "left"

type MaskProps = Partial<LayerProps> & {
  kind?: MaskKind
  /** Which side fades out, for `fade`. */
  direction?: MaskDirection
  /** 0–100. How much of the box the fade takes. */
  softness?: number
  /** Center for `vignette` and `spotlight`, e.g. "50% 30%". */
  at?: string
  children: React.ReactNode
}

function maskImage(
  kind: MaskKind,
  direction: MaskDirection,
  softness: number,
  at: string
) {
  const solid = 100 - softness

  switch (kind) {
    case "fade":
      return `linear-gradient(to ${direction}, #000 ${solid}%, transparent)`
    case "edges": {
      const edge = softness / 2
      return `linear-gradient(to right, transparent, #000 ${edge}%, #000 ${100 - edge}%, transparent), linear-gradient(to bottom, transparent, #000 ${edge}%, #000 ${100 - edge}%, transparent)`
    }
    case "vignette":
      return `radial-gradient(ellipse at ${at}, #000 ${solid}%, transparent)`
    case "spotlight":
      return `radial-gradient(circle at ${at}, #000, transparent ${Math.max(solid, 10)}%)`
  }
}

/**
 * Hides parts of its children with a soft alpha ramp. Give it a `placement`
 * to wrap other layers as one masked layer group.
 */
function Mask({
  kind = "fade",
  direction = "bottom",
  softness = 50,
  at = "50% 50%",
  placement,
  children,
  className,
  style,
  ...layer
}: MaskProps) {
  const image = maskImage(kind, direction, softness, at)
  const masking: React.CSSProperties = {
    maskImage: image,
    WebkitMaskImage: image,
    maskComposite: kind === "edges" ? "intersect" : undefined,
    WebkitMaskComposite: kind === "edges" ? "source-in" : undefined,
  }

  if (placement) {
    const props = layerProps({ ...layer, placement, className, style }, "mask")

    return (
      <div {...props} data-kind={kind} style={{ ...masking, ...props.style }}>
        {children}
      </div>
    )
  }

  return (
    <div
      data-slot="mask"
      data-kind={kind}
      className={className}
      style={{ ...masking, ...style }}
    >
      {children}
    </div>
  )
}

export { Mask, maskKinds, type MaskDirection, type MaskKind, type MaskProps }

import type * as React from "react"
import { cn } from "cn"

/**
 * Shared props for the layer primitives (Gradient, Noise, Pattern, Color
 * Grade, Distort, Mask). Put layers inside any `relative isolate` parent:
 * `behind` sits under the parent's content but above its background, `over`
 * sits on top of the content.
 */
type LayerPlacement = "behind" | "over"

type LayerBlend = Extract<
  React.CSSProperties["mixBlendMode"],
  | "normal"
  | "multiply"
  | "screen"
  | "overlay"
  | "soft-light"
  | "hard-light"
  | "color-dodge"
  | "color-burn"
  | "difference"
  | "luminosity"
  | "color"
>

type LayerProps = {
  placement?: LayerPlacement
  blend?: LayerBlend
  /** 0–1. */
  opacity?: number
  className?: string
  style?: React.CSSProperties
}

/** Class and style for an absolutely positioned, non-interactive layer. */
function layerProps(
  { placement = "behind", blend, opacity, className, style }: LayerProps,
  slot: string
) {
  return {
    "aria-hidden": true,
    "data-slot": slot,
    "data-placement": placement,
    className: cn(
      "pointer-events-none absolute inset-0 rounded-[inherit] forced-colors:hidden",
      placement === "behind" ? "-z-10" : "z-10",
      className
    ),
    style: { mixBlendMode: blend, opacity, ...style },
  } as const
}

/** SVG markup as a CSS url(), for textures that need no DOM. */
function svgUrl(svg: string) {
  return `url("data:image/svg+xml,${encodeURIComponent(svg)}")`
}

export { layerProps, svgUrl, type LayerBlend, type LayerPlacement, type LayerProps }
